@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Nunito:wght@600;700;800;900&display=swap');
:root{--navy:#101a39;--pink:#ff6794;--yellow:#ffe474;--cream:#fff8e9;--sky:#9ce8fa;--ink:#172448}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden}body{font-family:'Nunito',system-ui,sans-serif;color:var(--cream);background:radial-gradient(ellipse at 50% 43%,#253567 0%,#18264c 44%,#101833 100%);display:flex;align-items:center;justify-content:center}.game-shell{height:100dvh;width:min(100vw,calc(100dvh * 1.16));max-width:1450px;display:flex;flex-direction:column;padding:0 clamp(12px,3vw,42px);position:relative}.topbar,.bottom-bar{height:68px;min-height:54px;display:flex;align-items:center;justify-content:space-between;font-size:11px;letter-spacing:1.55px;font-weight:800}.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none}.brand b{color:var(--pink)}.brand-mark{display:grid;place-items:center;width:27px;height:27px;border-radius:9px;color:var(--navy);font-size:15px;background:var(--yellow);transform:rotate(-8deg);box-shadow:0 3px 0 #e7b844}.top-note{color:#a7b3d4;font:10px 'DM Mono',monospace;letter-spacing:1.2px}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#aaffb0;margin-right:8px;box-shadow:0 0 10px #aaffb0}.sound-button{border:1px solid #536287;border-radius:30px;background:transparent;color:var(--cream);padding:8px 13px;font-weight:900;letter-spacing:.8px;cursor:pointer}.sound-button span{font-size:9px;margin-left:4px}.stage-wrap{position:relative;flex:1;min-height:0;display:grid;place-items:center}.game-stage{height:100%;width:auto;aspect-ratio:4/5;max-width:100%;max-height:100%;position:relative;overflow:hidden;border:5px solid #fff3da;border-radius:16px;background:#67c9eb;box-shadow:0 0 0 2px #f4a36f,0 16px 55px #080f2670,0 0 65px #ff83a31c}.game-stage:after{content:'';position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 0 1px #fff9,inset 0 0 45px #143c7030;border-radius:10px;z-index:2}canvas{display:block;width:100%;height:100%;touch-action:none}.hud{position:absolute;z-index:3;left:14px;right:14px;top:13px;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none;text-shadow:0 2px 3px #344f7070}.hud-block{display:flex;flex-direction:column;gap:2px}.hud-label{font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#fff;font-weight:500}.hud-block strong{font:16px 'DM Mono',monospace;letter-spacing:1px;color:#fff}.hud-center{padding-top:2px}.stage-chip{border-radius:20px;background:#13254d9c;padding:6px 12px;color:#fff;font:9px 'DM Mono',monospace;letter-spacing:1px}.stage-chip b{color:var(--yellow);margin-left:4px}.hud-right{text-align:right}.hud-right .lives{font:14px 'Nunito',sans-serif;color:#ff607e;letter-spacing:1px}.overlay,.pause-screen,.end-screen{position:absolute;inset:0;z-index:4;display:flex;justify-content:center;align-items:center;background:linear-gradient(180deg,#1937652c,#1121474e);text-align:center}.intro-card{position:relative;width:min(88%,370px);padding:22px 24px 17px;border-radius:23px;background:#fff9e9;box-shadow:0 8px 0 #e3b77b,0 18px 36px #17284c70;color:var(--ink);border:2px solid white;transform:translateY(-3px)}.intro-card:before,.intro-card:after{content:'✦';position:absolute;color:#ffac59;font-size:24px}.intro-card:before{left:16px;top:49px}.intro-card:after{right:18px;top:116px;font-size:15px;color:#fa7898}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#e5798c;font-weight:500}.eyebrow span{color:#ffc344;font-size:13px;margin:0 3px}.intro-card h1{font-size:clamp(34px,6.1vw,53px);line-height:.83;letter-spacing:-2.2px;margin:13px 0 11px;font-weight:1000;color:#26375f;text-shadow:2px 2px #e2edf0}.intro-card h1 em{font-style:normal;color:#f26891}.intro-copy{font-size:12px;line-height:1.5;color:#6b7896;margin:0 0 13px}.plane-sticker{position:absolute;right:32px;top:54px;border-radius:50%;width:35px;height:35px;display:grid;place-items:center;background:#ffdd68;color:#e78958;font-size:23px;transform:rotate(15deg);border:2px solid white;box-shadow:0 3px 0 #efbd5b}.start-button{border:0;border-radius:11px;background:#f36891;color:#fff;font:900 14px 'Nunito',sans-serif;letter-spacing:1.4px;padding:13px 24px;min-width:190px;cursor:pointer;box-shadow:0 5px 0 #cb4c75,0 8px 14px #f15c8835;transition:transform .12s,box-shadow .12s}.start-button:hover{transform:translateY(-2px);box-shadow:0 7px 0 #cb4c75,0 10px 18px #f15c883b}.start-button:active{transform:translateY(3px);box-shadow:0 2px 0 #cb4c75}.start-button span{font-size:17px;margin-left:15px}.control-hint{margin:15px 0 0;color:#7f8aa2;font-size:9px}.control-hint kbd{font:8px 'DM Mono',monospace;background:#e9e9e0;color:#68738c;border-radius:4px;padding:3px 4px;box-shadow:0 1px #cdd0c9}.control-hint i{color:#f18a9a;font-style:normal;margin:0 3px}.touch-hint{display:none}.overlay-footer{position:absolute;bottom:15px;left:0;right:0;font:8px 'DM Mono',monospace;letter-spacing:2px;color:#ffffffc9}.overlay-footer span{color:#ffe474;margin:0 6px}.bottom-bar{font-size:9px;letter-spacing:1.6px;color:#abb6d4}.bottom-bar b{color:#ffdc70}.desktop-help{font:9px 'DM Mono',monospace;color:#f9f3dc}.desktop-help i{font-style:normal;color:#9eabc8;margin-left:4px}.footer-divider{margin:0 10px;color:#647294}.footer-logo{font-size:17px;color:#ffcf5a}.footer-logo b{color:#fff;font-size:11px}.pause-screen,.end-screen{background:#102148b8;backdrop-filter:blur(4px)}.pause-card,.end-card{padding:27px 24px;border-radius:22px;background:#fff8e9;color:#23365d;box-shadow:0 7px 0 #e4b774;width:min(88%,340px)}.pause-icon{color:#f2678e;font-size:30px;font-weight:900}.pause-card h2,.end-card h2{margin:7px 0 5px;font-size:23px;letter-spacing:-.7px}.pause-card p,.end-card p{color:#78829a;font-size:12px;margin:5px 0 17px}.pause-card button{background:#f2678e;color:white;border:0;border-radius:9px;padding:12px 25px;font-weight:900;letter-spacing:1px;cursor:pointer}.pause-card button b{margin-left:12px}.pause-card small{display:block;margin-top:15px;font:8px 'DM Mono',monospace;color:#939bb0;letter-spacing:1px}.end-emoji{font-size:37px}.end-card .eyebrow{margin-top:5px}.end-card h2{margin:10px 0 5px}.final-score{display:flex;justify-content:space-between;border-top:1px dashed #d1d1c7;border-bottom:1px dashed #d1d1c7;padding:10px 0;margin:15px 0;color:#79819a;font:9px 'DM Mono',monospace;letter-spacing:1px}.final-score b{color:#283b63;font-size:14px}.end-card .start-button{font-size:12px}.hidden{display:none!important}.mobile-controls{display:none}.toast{position:absolute;z-index:5;left:50%;top:19%;transform:translateX(-50%);white-space:nowrap;background:#fff6d8;color:#d96e85;border-radius:30px;padding:9px 16px;font-size:11px;font-weight:1000;letter-spacing:1px;box-shadow:0 3px 0 #e6b96b;animation:toast-pop .25s ease-out}@keyframes toast-pop{from{transform:translate(-50%,10px);opacity:0}to{transform:translate(-50%,0);opacity:1}}
@media (max-width:650px){.game-shell{width:100vw;padding:0 8px}.topbar,.bottom-bar{height:45px;min-height:42px}.topbar{font-size:9px}.top-note{display:none}.sound-button{padding:6px 10px}.game-stage{border-width:3px;border-radius:13px;aspect-ratio:4/5}.bottom-bar{font-size:7px;letter-spacing:1px}.desktop-help{display:none}.intro-card{width:88%;padding:20px 14px 14px}.intro-card h1{font-size:clamp(34px,10vw,49px)}.intro-copy{font-size:11px}.control-hint{display:none}.touch-hint{display:block;color:#8790a4;font-size:9px;margin:12px 0 0}.mobile-controls{display:block;position:absolute;z-index:3;inset:auto 0 0;height:28%;pointer-events:none}.stick-zone{position:absolute;left:4%;bottom:8%;width:100px;height:100px;display:grid;place-items:center;pointer-events:auto;touch-action:none}.stick-base{width:74px;height:74px;border-radius:50%;background:#25395c49;border:2px solid #ffffff79;display:grid;place-items:center;box-shadow:inset 0 0 0 5px #ffffff18}.stick-knob{width:34px;height:34px;border-radius:50%;background:#fff8e9bc;border:2px solid #fff;box-shadow:0 2px 6px #19305055}.fire-button{position:absolute;right:5%;bottom:10%;width:67px;height:67px;border:2px solid #fff;background:#f26891df;color:#fff;border-radius:50%;box-shadow:0 4px 0 #bd4b6c;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:auto;touch-action:none}.fire-button span{font-size:22px;line-height:20px}.fire-button small{font:8px 'DM Mono',monospace;letter-spacing:1px}.hud{left:10px;right:10px;top:10px}.hud-label{font-size:8px}.hud-block strong{font-size:13px}.hud-right .lives{font-size:12px}.overlay-footer{bottom:13px;font-size:7px}.plane-sticker{right:24px;top:48px;width:29px;height:29px;font-size:19px}}
@media(max-height:570px) and (orientation:landscape){.game-shell{width:100vw;height:100dvh;padding:0 8px}.topbar,.bottom-bar{height:35px;min-height:30px}.game-stage{height:calc(100% - 4px);aspect-ratio:4/5}.intro-card{padding:10px 16px;width:310px}.intro-card h1{font-size:34px;margin:8px 0}.intro-copy{font-size:10px;margin-bottom:8px}.start-button{padding:9px 20px;min-width:155px}.control-hint{margin-top:9px}.plane-sticker{top:35px}.overlay-footer{bottom:7px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { score:$('score'), level:$('level'), lives:$('lives'), overlay:$('overlay'), pause:$('pauseScreen'), end:$('endScreen'), toast:$('toast') };
  const W=480,H=600;
  let running=false,paused=false,gameOver=false,last=0,elapsed=0,score=0,lives=3,level=1,spawnClock=0,fireClock=0,toastClock=0;
  let player, enemies=[],shots=[],enemyShots=[],particles=[],pickups=[],clouds=[],stars=[],keys={},touch={x:0,y:0,fire:false},boss=null,bossTimer=0,soundOn=false,audio=null;
  let highScore=Number(localStorage.getItem('pipoca-high-score')||0);
  function resize(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  function makeCloud(x,y,s=1){return{x,y,s,speed:14+Math.random()*20,kind:Math.random()>.5?0:1}}
  for(let i=0;i<11;i++)clouds.push(makeCloud(Math.random()*W,Math.random()*H,.55+Math.random()*.8));
  for(let i=0;i<38;i++)stars.push({x:Math.random()*W,y:Math.random()*H,r:1+Math.random()*2,phase:Math.random()*7});
  function reset(){score=0;lives=3;level=1;elapsed=0;spawnClock=.5;fireClock=0;enemies=[];shots=[];enemyShots=[];particles=[];pickups=[];boss=null;bossTimer=0;player={x:W/2,y:H-105,r:17,invuln:0,tilt:0,power:1};updateHud()}
  function start(){reset();running=true;paused=false;gameOver=false;ui.overlay.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');last=performance.now();requestAnimationFrame(loop);playTone(480,.08)}
  function updateHud(){ui.score.textContent=String(score).padStart(6,'0');ui.level.textContent=String(level).padStart(2,'0');ui.lives.textContent=lives>0?'♥ '.repeat(lives).trim():'—'}
  function playTone(freq,duration=.08,type='sine'){if(!soundOn)return;try{audio ||= new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.value=.045;o.connect(g);g.connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.stop(audio.currentTime+duration)}catch(_){}}
  function showToast(text){ui.toast.textContent='✦ '+text;ui.toast.classList.remove('hidden');toastClock=1.5}
  function pause(){if(!running||gameOver)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);if(!paused){last=performance.now();requestAnimationFrame(loop)}}
  function finish(win=false){running=false;gameOver=true;ui.end.classList.remove('hidden');$('endEmoji').textContent=win?'🏆':'💫';$('endTitle').textContent=win?'VOCÊ É DEMAIS!':'FIM DE VOO!';$('endCopy').textContent=win?'O céu voltou a ficar tranquilo.':'Até os melhores pilotos precisam de uma pausa.';$('finalScore').textContent=String(score).padStart(6,'0');$('endScreen').querySelector('.eyebrow').textContent=win?'MISSÃO CONCLUÍDA':'TENTE MAIS UMA VEZ';if(score>highScore){highScore=score;localStorage.setItem('pipoca-high-score',String(score))}playTone(win?680:180,.28,'triangle')}
  function addParticle(x,y,color,n=8){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=35+Math.random()*130;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+Math.random()*.5,max:.85,size:2+Math.random()*4,color})}}
  function shoot(){if(fireClock>0)return;fireClock=player.power>1?.13:.2;const spread=player.power>1?[-10,0,10]:[0];spread.forEach(dx=>shots.push({x:player.x+dx,y:player.y-22,v:440,r:4}));playTone(610,.035,'square')}
  function spawnEnemy(){if(boss)return;let type=Math.random(),x=40+Math.random()*(W-80);if(type<.58){enemies.push({x,y:-35,hp:1,max:1,v:85+level*5,r:18,type:'bee',phase:Math.random()*6,shoot:1.6+Math.random()*1.5})}else if(type<.88){enemies.push({x,y:-40,hp:2,max:2,v:62+level*3,r:22,type:'bird',phase:Math.random()*6,shoot:1.2+Math.random()})}else{enemies.push({x,y:-40,hp:3,max:3,v:48,r:23,type:'pig',phase:Math.random()*6,shoot:2})}}
  function makeBoss(){boss={x:W/2,y:-90,hp:35+level*5,max:35+level*5,v:54,shoot:1.1,phase:0};showToast('CHEFE À VISTA!');playTone(160,.35,'sawtooth')}
  function fireEnemy(e){const dx=player.x-e.x,dy=player.y-e.y,len=Math.hypot(dx,dy)||1;enemyShots.push({x:e.x,y:e.y+12,vx:dx/len*145,vy:dy/len*145,r:6});}
  function update(dt){elapsed+=dt;level=1+Math.floor(elapsed/24);if(elapsed>0&&elapsed%24<dt)showToast('FASE '+String(level).padStart(2,'0'));
    clouds.forEach(c=>{c.y+=c.speed*dt;if(c.y>H+55){c.y=-60;c.x=Math.random()*W}});stars.forEach(s=>s.y+=s.r*13*dt);stars.forEach(s=>{if(s.y>H)s.y=0});
    const left=keys.ArrowLeft||keys.a||keys.A,right=keys.ArrowRight||keys.d||keys.D,up=keys.ArrowUp||keys.w||keys.W,down=keys.ArrowDown||keys.s||keys.S;
    let ix=(right?1:0)-(left?1:0)+touch.x,iy=(down?1:0)-(up?1:0)+touch.y,mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag}
    player.x=Math.max(24,Math.min(W-24,player.x+ix*260*dt));player.y=Math.max(90,Math.min(H-42,player.y+iy*260*dt));player.tilt+=(ix*.45-player.tilt)*Math.min(1,dt*8);player.invuln=Math.max(0,player.invuln-dt);fireClock=Math.max(0,fireClock-dt);if(keys[' ']||touch.fire)shoot();
    if(!boss){spawnClock-=dt;if(spawnClock<=0){spawnEnemy();spawnClock=Math.max(.38,1.12-level*.055)+Math.random()*.55}if(elapsed>42&&bossTimer<=0){makeBoss();bossTimer=elapsed+48}}else{boss.phase+=dt;boss.y=Math.min(105,boss.y+boss.v*dt);boss.x=W/2+Math.sin(boss.phase*1.05)*115;boss.shoot-=dt;if(boss.shoot<=0){for(let a=-1;a<=1;a++)enemyShots.push({x:boss.x+a*35,y:boss.y+20,vx:a*55,vy:155,r:8});boss.shoot=.85}if(boss.hp<=0){addParticle(boss.x,boss.y,'#ffb54d',36);score+=1500;boss=null;bossTimer=elapsed+48;updateHud();showToast('CHEFE DERROTADO!') }}
    shots.forEach(s=>s.y-=s.v*dt);shots=shots.filter(s=>s.y>-15);
    enemies.forEach(e=>{e.y+=e.v*dt;e.phase+=dt*2;e.x+=Math.sin(e.phase)*35*dt;e.shoot-=dt;if(e.shoot<=0&&e.y>20&&e.y<H-100){fireEnemy(e);e.shoot=e.type==='bird'?1.5:2.1}});enemies=enemies.filter(e=>e.y<H+40);
    enemyShots.forEach(s=>{s.x+=s.vx*dt;s.y+=s.vy*dt});enemyShots=enemyShots.filter(s=>s.y<H+20&&s.x>-20&&s.x<W+20);
    for(let i=shots.length-1;i>=0;i--){let hit=false;for(let j=enemies.length-1;j>=0;j--){const e=enemies[j];if(Math.hypot(shots[i].x-e.x,shots[i].y-e.y)<e.r+shots[i].r){e.hp--;shots.splice(i,1);hit=true;if(e.hp<=0){addParticle(e.x,e.y,e.type==='bee'?'#ffcd58':e.type==='bird'?'#ff809b':'#9b75db');score+=e.max===1?100:160;if(Math.random()<.08)pickups.push({x:e.x,y:e.y,type:'star',r:12});enemies.splice(j,1);updateHud()}break}}if(!hit&&boss&&Math.hypot(shots[i].x-boss.x,shots[i].y-boss.y)<63){boss.hp--;shots.splice(i,1)}}
    if(boss){for(let i=shots.length-1;i>=0;i--){if(Math.abs(shots[i].x-boss.x)<61&&Math.abs(shots[i].y-boss.y)<47){boss.hp--;shots.splice(i,1)}}}
    pickups.forEach(p=>p.y+=85*dt);pickups=pickups.filter(p=>p.y<H+20);for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];if(Math.hypot(player.x-p.x,player.y-p.y)<28){player.power=Math.min(3,player.power+1);score+=50;pickups.splice(i,1);showToast('TIRO TURBINADO!');playTone(900,.1)}}
    if(player.invuln<=0){let collided=false;for(let i=enemyShots.length-1;i>=0;i--){if(Math.hypot(player.x-enemyShots[i].x,player.y-enemyShots[i].y)<player.r+enemyShots[i].r){enemyShots.splice(i,1);collided=true;break}}if(!collided){for(let i=enemies.length-1;i>=0;i--)if(Math.hypot(player.x-enemies[i].x,player.y-enemies[i].y)<player.r+enemies[i].r*.7){addParticle(enemies[i].x,enemies[i].y,'#ffc752',9);enemies.splice(i,1);collided=true;break}}if(!collided&&boss&&Math.abs(player.x-boss.x)<55&&Math.abs(player.y-boss.y)<40)collided=true;if(collided){lives--;player.invuln=1.7;player.power=Math.max(1,player.power-1);addParticle(player.x,player.y,'#fff2a1',15);updateHud();playTone(130,.2,'sawtooth');if(lives<=0){finish(false);return}}}
    particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;p.life-=dt});particles=particles.filter(p=>p.life>0);if(toastClock>0){toastClock-=dt;if(toastClock<=0)ui.toast.classList.add('hidden')}
  }
  function outlined(color='#26385d',width=3){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round'}
  function cloudDraw(c){ctx.save();ctx.translate(c.x,c.y);ctx.scale(c.s,c.s);ctx.globalAlpha=.48;ctx.fillStyle=c.kind?'#fff':'#fff8df';ctx.beginPath();ctx.ellipse(0,6,36,13,0,0,Math.PI*2);ctx.ellipse(-16,1,16,15,0,0,Math.PI*2);ctx.ellipse(0,-6,19,21,0,0,Math.PI*2);ctx.ellipse(18,1,17,14,0,0,Math.PI*2);ctx.fill();ctx.restore()}
  function drawPlane(x,y,scale=1,tilt=0,enemy=false){ctx.save();ctx.translate(x,y);ctx.rotate(tilt);ctx.scale(scale,scale);const main=enemy?(enemy==='bee'?'#ffc943':enemy==='bird'?'#f6788f':'#a47bdd'):'#ff6f96';
    // wings and body
    ctx.fillStyle=enemy?'#38476e':'#f8e9c8';ctx.beginPath();ctx.ellipse(-18,1,13,7,-.18,0,Math.PI*2);ctx.ellipse(18,1,13,7,.18,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=main;ctx.beginPath();ctx.moveTo(-25,-4);ctx.lineTo(-9,-9);ctx.lineTo(-10,-19);ctx.lineTo(-3,-21);ctx.lineTo(3,-21);ctx.lineTo(10,-19);ctx.lineTo(9,-9);ctx.lineTo(25,-4);ctx.lineTo(25,4);ctx.lineTo(9,1);ctx.lineTo(7,15);ctx.lineTo(14,20);ctx.lineTo(12,24);ctx.lineTo(0,20);ctx.lineTo(-12,24);ctx.lineTo(-14,20);ctx.lineTo(-7,15);ctx.lineTo(-9,1);ctx.lineTo(-25,4);ctx.closePath();ctx.fill();outlined(enemy?'#37456c':'#d84976',2.4);ctx.stroke();
    ctx.fillStyle=enemy?'#ffdc63':'#ffca57';ctx.beginPath();ctx.ellipse(0,-8,5,10,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#b8f2f7';ctx.beginPath();ctx.ellipse(0,-10,3.3,5.1,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=1.2;ctx.stroke();
    // propeller
    ctx.strokeStyle='#fff4dc';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-9,-22);ctx.lineTo(9,-22);ctx.stroke();ctx.fillStyle='#fff4dc';ctx.beginPath();ctx.arc(0,-22,2.4,0,Math.PI*2);ctx.fill();
    ctx.restore()}
